class Solution {
    public int minMeetingRooms(int[][] intervals) {
        java.util.Arrays.sort(intervals, (a, b) -> {
            int byStart = Integer.compare(a[0], b[0]);
            return byStart != 0 ? byStart : Integer.compare(a[1], b[1]);
        });
        java.util.PriorityQueue<Integer> activeEnds = new java.util.PriorityQueue<>();
        int rooms = 0;
        for (int[] interval : intervals) {
            while (!activeEnds.isEmpty() && activeEnds.peek() <= interval[0]) {
                activeEnds.poll();
            }
            activeEnds.offer(interval[1]);
            rooms = Math.max(rooms, activeEnds.size());
        }
        return rooms;
    }
}

class Solution {
    public int minMeetingRooms(int[][] intervals) {
        int n = intervals.length;
        int[] starts = new int[n];
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = intervals[i][0];
            ends[i] = intervals[i][1];
        }
        java.util.Arrays.sort(starts);
        java.util.Arrays.sort(ends);
        int rooms = 0;
        int active = 0;
        int endPtr = 0;
        for (int start : starts) {
            if (start < ends[endPtr]) {
                active++;
            } else {
                endPtr++;
            }
            rooms = Math.max(rooms, active);
        }
        return rooms;
    }
}

import java.util.*;

class Solution {
    public int minMeetingRooms(int[][] intervals) {
        TreeMap<Integer, Integer> diff = new TreeMap<>();
        for (int[] interval : intervals) {
            diff.merge(interval[0], 1, Integer::sum);
            diff.merge(interval[1], -1, Integer::sum);
        }
        int active = 0;
        int rooms = 0;
        for (int delta : diff.values()) {
            active += delta;
            rooms = Math.max(rooms, active);
        }
        return rooms;
    }
}

import java.util.*;

class Solution {
    public int minMeetingRooms(int[][] intervals) {
        int[][] events = new int[intervals.length * 2][2];
        int index = 0;
        for (int[] interval : intervals) {
            events[index++] = new int[]{interval[0], 1};
            events[index++] = new int[]{interval[1], -1};
        }
        java.util.Arrays.sort(events, (a, b) -> {
            int byTime = Integer.compare(a[0], b[0]);
            return byTime != 0 ? byTime : Integer.compare(a[1], b[1]);
        });
        int active = 0;
        int rooms = 0;
        for (int[] event : events) {
            active += event[1];
            rooms = Math.max(rooms, active);
        }
        return rooms;
    }
}

class Solution {
    public int minMeetingRooms(int[][] intervals) {
        int maxEnd = 0;
        for (int[] interval : intervals) {
            maxEnd = Math.max(maxEnd, interval[1]);
        }
        int[] diff = new int[maxEnd + 1];
        for (int[] interval : intervals) {
            diff[interval[0]]++;
            diff[interval[1]]--;
        }
        int active = 0;
        int rooms = 0;
        for (int time = 0; time <= maxEnd; time++) {
            active += diff[time];
            rooms = Math.max(rooms, active);
        }
        return rooms;
    }
}
